import json
from pathlib import Path

ATTACKS = ['prompt_injection','sycophancy','score_manipulation','verbosity_bias','position_bias','authority_bias']
DATASETS = ['mmlu', 'arc_challenge']

# ── API models: read pre-computed ASR from scoring individual_scores ──
API_MODELS = ['claude-opus-4-6','gpt-5.5','gemini-3.1-pro-preview','gpt-4.1',
              'claude-sonnet-4-6','gpt-4.1-nano','gemini-3.5-flash','gpt-4.1-mini','claude-3-haiku']
api_dir = Path('scoring/results/plan001/individual_scores')

api_asr = {}
for mid in API_MODELS:
    api_asr[mid] = {}
    for atk in ATTACKS:
        asrs = []
        for ds in DATASETS:
            fp = api_dir / f'{mid}__{ds}__{atk}.json'
            if fp.exists():
                with open(fp) as f:
                    d = json.load(f)
                asrs.append(d.get('asr', 0))
        api_asr[mid][atk] = sum(asrs)/len(asrs) if asrs else None

# ── Local models: compute ASR from checkpoint files ──
LOCAL_MODELS = ['qwen2.5-72b','llama3.1-70b','mistral-large','qwen2.5-32b','qwen2.5-14b','llama3.1-8b']

# Load checkpoints
ckpt1 = json.load(open('artifacts/results/_taxonomy_checkpoint.json'))  # verbosity, position, authority
ckpt2 = json.load(open('artifacts/results/_step2v3_checkpoint.json'))   # prompt_injection, sycophancy, score_manipulation

def compute_asr_from_scores(clean_scores, attacked_scores):
    # ASR = fraction where clean winner was A but attacked changed it
    n_flipped = 0
    n_valid = 0
    for c, a in zip(clean_scores, attacked_scores):
        cw = c.get('winner')
        aw = a.get('winner')
        if cw in ('A','B','tie') and aw in ('A','B','tie'):
            n_valid += 1
            if cw != aw:
                n_flipped += 1
    return n_flipped / n_valid if n_valid > 0 else 0

local_asr = {}
for mid in LOCAL_MODELS:
    local_asr[mid] = {}
    for atk in ATTACKS:
        # Determine which checkpoint has this attack
        ckpt = None
        if atk in ('verbosity_bias','position_bias','authority_bias'):
            ckpt = ckpt1
        elif atk in ('prompt_injection','sycophancy','score_manipulation'):
            ckpt = ckpt2

        asrs = []
        for ds in DATASETS:
            clean = ckpt.get('clean_scores',{}).get(ds,{}).get(mid,[])
            attacked = ckpt.get('attacked_scores',{}).get(ds,{}).get(atk,{}).get(mid,[])
            if clean and attacked:
                asr_val = compute_asr_from_scores(clean, attacked)
                asrs.append(asr_val)
        local_asr[mid][atk] = sum(asrs)/len(asrs) if asrs else None

# Combine and output
result = {'api': api_asr, 'local': local_asr}
print(json.dumps(result, indent=2))
"
